96	static struct xiaozhi_app_s *s_mcp_app = NULL; /* for MCP send_json callback */
97	
98	/* Forward declaration (defined later in this file). */
99	
100	static int send_json(struct xiaozhi_app_s *app, cJSON *root);
101	
102	/* MCP tool: send_json wrapper (app context via static pointer).
103	 * Wraps the JSON-RPC response in the xiaozhi transport format:
104	 * {"type":"mcp","payload":{...}}
105	 */
106	
107	static int mcp_send_json(cJSON *msg)
108	{
109	  if (s_mcp_app == NULL)
110	    {
111	      return -1;
112	    }
113	
114	  /* Wrap in transport format: {"type":"mcp","payload":<original>} */
115	
116	  cJSON *wrapper = cJSON_CreateObject();
117	  cJSON_AddStringToObject(wrapper, "type", "mcp");
118	  cJSON *payload = cJSON_Duplicate(msg, 1);
119	  cJSON_AddItemToObject(wrapper, "payload", payload);
120	
121	  int ret = send_json(s_mcp_app, wrapper);
122	  cJSON_Delete(wrapper);
123	  return ret;
124	}
