269	/****************************************************************************
270	 * Listening动画函数
271	 ****************************************************************************/
272	
273	/* 生成目标高度 */
274	static void wave_gen_targets(void)
275	{
276	    for (int i = 0; i < BAR_COUNT; i++) {
277	        float t = (float)i / BAR_COUNT;
278	        float env = expf(-5.0f * (t - 0.5f) * (t - 0.5f));
279	        float r = fabsf(sinf(t * 13.7f + s_tick * 0.9f)) * 0.4f
280	                + fabsf(cosf(t * 23.1f - s_tick * 0.6f)) * 0.35f
281	                + fabsf(sinf(t * 7.3f + s_tick * 1.4f)) * 0.25f;
282	        s_bar_tgt[i] = r * env;
283	    }
284	}
285	
286	/* 定时器回调 */
287	static void wave_tick_cb(lv_timer_t *t)
288	{
289	    (void)t;
290	
291	    pthread_mutex_lock(&s_ui_mutex);
292	
293	    s_tick += 0.15f;
294	
295	    /* 每次都生成新的目标高度，让动画持续变化 */
296	    wave_gen_targets();
297	
298	    /* 更新每个柱子的高度和位置 */
299	    for (int i = 0; i < BAR_COUNT; i++) {
300	        float speed = 0.1f + (float)i / BAR_COUNT * 0.1f;  /* 加快响应速度 */
301	        s_bar_h[i] += (s_bar_tgt[i] - s_bar_h[i]) * speed;
302	
303	        /* 计算高度（像素） */
304	        int h = (int)(s_bar_h[i] * BAR_MAX_HEIGHT);
305	        if (h < 4) h = 4;
306	
307	        /* 更新柱子对象的高度和位置（保持底部对齐） */
308	        if (s_bars[i] != NULL) {
309	            lv_obj_set_height(s_bars[i], h);
310	            /* 底部对齐：y坐标 = 容器高度 - 柱子高度 */
311	            lv_obj_set_y(s_bars[i], BAR_MAX_HEIGHT + 10 - h);
312	        }
313	    }
314	
315	    pthread_mutex_unlock(&s_ui_mutex);
316	}
