318	/* 启动Listening动画 */
319	void wave_anim_start(lv_obj_t *parent)
320	{
321	    /* 如果已经创建，先停止 */
322	    wave_anim_stop();
323	
324	    memset(s_bar_h, 0, sizeof(s_bar_h));
325	    memset(s_bar_tgt, 0, sizeof(s_bar_tgt));
326	    s_tick = 0;
327	
328	    /* 创建柱子容器 */
329	    s_bar_container = lv_obj_create(parent);
330	    lv_obj_set_size(s_bar_container, 200, BAR_MAX_HEIGHT + 10);  /* 容器高度 */
331	    lv_obj_align(s_bar_container, LV_ALIGN_TOP_MID, 0, 55);     /* 在status_label(60)上面一点 */
332	    lv_obj_set_style_bg_opa(s_bar_container, LV_OPA_TRANSP, 0);
333	    lv_obj_set_style_border_width(s_bar_container, 0, 0);
334	    lv_obj_set_style_pad_all(s_bar_container, 0, 0);
335	    lv_obj_set_style_pad_top(s_bar_container, 0, 0);
336	    lv_obj_set_style_pad_bottom(s_bar_container, 0, 0);
337	    lv_obj_set_style_pad_left(s_bar_container, 0, 0);
338	    lv_obj_set_style_pad_right(s_bar_container, 0, 0);
339	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_SCROLLABLE);
340	    lv_obj_clear_flag(s_bar_container, LV_OBJ_FLAG_HIDDEN);
341	
342	    /* 计算起始位置 */
343	    int total_width = BAR_COUNT * BAR_WIDTH + (BAR_COUNT - 1) * BAR_GAP;
344	    int x_start = (200 - total_width) / 2;
345	
346	    /* 创建7个柱子，底部对齐在容器底部 */
347	    for (int i = 0; i < BAR_COUNT; i++) {
348	        s_bars[i] = lv_obj_create(s_bar_container);
349	        lv_obj_set_size(s_bars[i], BAR_WIDTH, 4);  /* 初始高度4像素 */
350	        /* 柱子底部对齐：y坐标 = 容器高度 - 初始高度 */
351	        lv_obj_set_pos(s_bars[i], x_start + i * (BAR_WIDTH + BAR_GAP), BAR_MAX_HEIGHT + 10 - 4);
352	        lv_obj_set_style_bg_color(s_bars[i], lv_color_hex(BAR_COLOR), 0);
353	        lv_obj_set_style_bg_opa(s_bars[i], LV_OPA_COVER, 0);
354	        lv_obj_set_style_radius(s_bars[i], BAR_WIDTH / 2, 0);  /* 圆角 */
355	        lv_obj_set_style_border_width(s_bars[i], 0, 0);
356	        lv_obj_clear_flag(s_bars[i], LV_OBJ_FLAG_HIDDEN);
357	    }
358	
359	    /* 创建"我正在听..." label */
360	    s_listen_label = lv_label_create(parent);
361	    lv_label_set_text(s_listen_label, "我正在听...");
362	    lv_obj_set_style_text_font(s_listen_label, font_manager_get_font(FONT_LARGE), 0);
363	    lv_obj_set_style_text_color(s_listen_label, lv_color_hex(0xFF6900), 0);
364	    lv_obj_align(s_listen_label, LV_ALIGN_TOP_MID, 0, 170);  /* 在动画下方 */
365	
366	    wave_gen_targets();
367	    s_timer = lv_timer_create(wave_tick_cb, ANIM_MS, NULL);
368	
369	    printf("[xiaozhi] wave_anim_start: created %d bars\n", BAR_COUNT);
370	}
