389	/* 定时器回调：更新圆点大小 */
390	static void think_tick_cb(lv_timer_t *t)
391	{
392	    (void)t;
393	
394	    pthread_mutex_lock(&s_ui_mutex);
395	
396	    s_think_tick++;
397	
398	    for (int i = 0; i < DOT_COUNT; i++) {
399	        float phase = (float)(s_think_tick - i * 2) / 4.0f;  /* 调整相位 */
400	        float tri = 1.0f - fabsf(fmodf(phase, 2.0f) - 1.0f);
401	        int size = (int)(DOT_SIZE * (0.4f + tri * 0.6f));
402	
403	        if (s_dots[i] != NULL) {
404	            lv_obj_set_size(s_dots[i], size, size);
405	            lv_obj_set_style_radius(s_dots[i], size / 2, 0);
406	        }
407	    }
408	
409	    pthread_mutex_unlock(&s_ui_mutex);
410	}
