451	    lv_obj_set_style_text_color(s_think_label, lv_color_hex(0xFF6900), 0);
452	    lv_obj_align(s_think_label, LV_ALIGN_TOP_MID, 0, 120);  /* 在动画下方 */
453	
454	    s_think_timer = lv_timer_create(think_tick_cb, DOT_ANIM_MS, NULL);
