472	/*====================================================
473	 * 手势事件处理：右滑返回到applist
474	 *====================================================*/
475	static void xiaozhi_gesture_event_cb(lv_event_t *e)
476	{
477	    lv_event_code_t code = lv_event_get_code(e);
478	    lv_indev_t *indev = lv_indev_active();
479	    if (!indev) return;
480	
481	    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
482	
483	    switch (code)
484	    {
485	    case LV_EVENT_GESTURE:
486	        if (dir == LV_DIR_RIGHT)
487	        {
488	            LV_LOG_USER("xiaozhi: LV_DIR_RIGHT - exit to applist");
489	            /* 隐藏AI应用UI */
490	            xiaozhi_voice_delete();
491	            /* 返回到applist */
492	            nav_return_from_app();
493	        }
494	        break;
495	    default:
496	        break;
497	    }
498	}
