507	/* Speak button UX tuning. */
508	#define XZ_MIN_INPUT_MS     500    /* press shorter than this = accidental */
509	/* RMS threshold for "did the user actually speak?". Measured on this board:
510	 * silence ~0, normal speech ~60-100. So 30 sits clearly above the noise
511	 * floor but below real speech. If you see false rejects, lower it; if
512	 * ambient noise triggers false accepts, raise it. */
513	#define XZ_SPEAK_RMS_THRESH 30
514	
515	/* Audio capture buffer: while Speak is held, opus frames are captured into
516	 * this ring of buffers (NOT sent yet). On release, if the input is valid
517	 * (min duration + RMS), the whole buffer is drained to the server in one
518	 * shot between listen:start and listen:stop. ~10s max hold at 60ms/frame. */
519	#define XZ_FRAME_BUF_COUNT  170    /* 170 * 60ms ~= 10.2s max */
520	
521	struct xz_frame_buf_s
522	{
523	  uint16_t len;                    /* opus payload length, 0 = empty slot */
524	  uint16_t pad;
525	  uint8_t  data[XZ_OPUS_MAX];
526	};
527	
528	/* 小智二进制音频帧头（协议版本 v3）。
529	 * 服务器靠这个头定位 opus 负载长度；直接发裸 opus 帧会导致服务器把前 4
530	 * 字节误当头解析，音频错位/截断，ASR 识别不准。
531	 *   type=0 (OPUS), reserved=0, payload_size=htons(帧长) */
532	struct __attribute__((packed)) xz_binary_hdr_s
533	{
534	  uint8_t  type;
535	  uint8_t  reserved;
536	  uint16_t payload_size;
537	};
