625	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
626	 * equivalents so the limited CJK font (basic ideographs only) can render
627	 * all visible characters without falling back to [][].
628	 */
629	static void sanitize_text(char *dst, size_t dstsize, const char *src)
630	{
631	  size_t di = 0;
632	  const unsigned char *s = (const unsigned char *)src;
633	
634	  while (*s && di < dstsize - 1)
635	    {
636	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
637	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
638	          s[2] >= 0x80 && s[2] < 0xc0)
639	        {
640	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
641	                            ((unsigned int)(s[1] & 0x3f) << 6) |
642	                            ((unsigned int)(s[2] & 0x3f));
643	          const char *r = NULL;
644	
645	          switch (cp)
646	            {
647	              case 0xff0c: r = ",";  break;  /* ， */
648	              case 0x3002: r = ".";  break;  /* 。 */
649	              case 0xff01: r = "!";  break;  /* ！ */
650	              case 0xff1f: r = "?";  break;  /* ？ */
651	              case 0xff1a: r = ":";  break;  /* ： */
652	              case 0xff1b: r = ";";  break;  /* ； */
653	              case 0x3001: r = ",";  break;  /* 、 */
654	              case 0x201c: r = "\""; break;  /* " */
655	              case 0x201d: r = "\""; break;  /* " */
656	              case 0x2018: r = "'";  break;  /* ' */
657	              case 0x2019: r = "'";  break;  /* ' */
658	              case 0xff08: r = "(";  break;  /* （ */
659	              case 0xff09: r = ")";  break;  /* ） */
660	              case 0x300a: r = "<<"; break;  /* 《 */
661	              case 0x300b: r = ">>"; break;  /* 》 */
662	              case 0x2026: r = "..."; break; /* … */
663	              case 0x2014: r = "--"; break;  /* — */
664	              default:
665	                {
666	                  /* Keep the original character if it's in CJK range */
667	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
668	                    {
669	                      dst[di++] = s[0];
670	                      dst[di++] = s[1];
671	                      dst[di++] = s[2];
672	                    }
673	                  else
674	                    {
675	                      /* Unknown char: skip */
676	                    }
677	                  s += 3;
678	                  continue;
679	                }
680	            }
681	
682	          /* Write replacement string */
683	          while (*r && di < dstsize - 1)
684	            {
685	              dst[di++] = *r++;
686	            }
687	
688	          s += 3;
689	        }
690	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
691	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
692	        {
693	          s += 2;
694	        }
695	      /* ASCII */
696	      else if (s[0] < 0x80)
697	        {
698	          dst[di++] = *s++;
699	        }
700	      else
701	        {
702	          /* Invalid UTF-8 byte, skip */
703	          s++;
704	        }
705	    }
706	
707	  dst[di] = '\0';
708	}
