725	/* Capture thread: while Speak is held, read opus frames from the mic and
726	 * store them in the frame buffer (NOT sent yet). Stops when the user
727	 * releases Speak (capture_stop) or the buffer fills.
728	 */
729	static void *capture_thread(void *arg)
730	{
731	  struct xiaozhi_app_s *app = arg;
732	
733	  /* start_capture touches the SMF codec and can block ~150ms (codec init).
734	   * It MUST run off the LVGL thread, otherwise the touch indev loses the
735	   * PRESSED state and fires a spurious RELEASED. */
736	  int ret = xiaozhi_audio_start_capture(app->audio);
737	  app->capture_started = true;   /* set even on failure so round thread stops */
738	  if (ret != 0)
739	    {
740	      printf("[xiaozhi] capture: start_capture failed: %d\n", ret);
741	      app->capturing = false;
742	      return NULL;
743	    }
744	
745	  printf("[xiaozhi] capture: buffering opus frames\n");
746	
747	  while (app->capturing && !app->capture_stop && app->ws_connected &&
748	         app->frame_buf_cnt < XZ_FRAME_BUF_COUNT)
749	    {
750	      ssize_t n = xiaozhi_audio_read_opus(app->audio,
751	                                          app->frame_buf[app->frame_buf_cnt].data,
752	                                          XZ_OPUS_MAX);
753	      if (n < 0)
754	        {
755	          /* -EINTR/-ENODATA when the recorder is stopped on release. */
756	          printf("[xiaozhi] capture read err: %zd (frames so far=%d)\n",
757	                 n, app->frame_buf_cnt);
758	          break;
759	        }
760	
761	      if (n > 0)
762	        {
763	          app->frame_buf[app->frame_buf_cnt].len = (uint16_t)n;
764	          app->frame_buf_cnt++;
765	        }
766	    }
767	
768	  printf("[xiaozhi] capture: buffered %d frames\n", app->frame_buf_cnt);
769	  return NULL;
770	}
