772	/* Drain all buffered opus frames to the server as binary frames, wrapping
773	 * each in the BinaryProtocol3 header. Called after the validity check passes.
774	 */
775	static void drain_buffer_to_server(struct xiaozhi_app_s *app)
776	{
777	  int cnt = app->frame_buf_cnt;
778	  for (int i = 0; i < cnt && app->ws_connected; i++)
779	    {
780	      uint16_t n = app->frame_buf[i].len;
781	      if (n == 0)
782	        {
783	          continue;
784	        }
785	
786	      struct xz_binary_hdr_s *hdr;
787	      uint8_t outbuf[sizeof(*hdr) + XZ_OPUS_MAX];
788	
789	      hdr = (struct xz_binary_hdr_s *)outbuf;
790	      hdr->type = 0;                 /* 0 = OPUS */
791	      hdr->reserved = 0;
792	      hdr->payload_size = htons(n);
793	      memcpy(outbuf + sizeof(*hdr), app->frame_buf[i].data, n);
794	
795	      int ret = xiaozhi_ws_send_binary(&app->ws, outbuf, sizeof(*hdr) + n);
796	      if (ret != 0)
797	        {
798	          printf("[xiaozhi] drain send err: %d (frame %d)\n", ret, i);
799	          break;
800	        }
801	    }
802	
803	  printf("[xiaozhi] drain: sent %d/%d frames\n", cnt, cnt);
804	}
