807	/* Background receive thread: parses server messages and feeds TTS audio to
808	 * the player. Runs for the lifetime of the wss connection — it is NOT a
809	 * one-shot loop. Per-turn events (stt, tts start/stop) flip flags that the
810	 * dialog-round thread waits on.
811	 *
812	 * The handshake phase (hello + MCP tools/list) is also handled here: the
813	 * connect thread sends hello, then joins (waits on) this thread's processing
814	 * of the hello response + MCP exchange via the handshake_done flag.
815	 */
816	static void *recv_thread(void *arg)
817	{
818	  struct xiaozhi_app_s *app = arg;
819	
820	  while (app->ws_connected)
821	    {
822	      const uint8_t *payload;
823	      size_t plen;
824	      bool is_binary;
825	      int ret;
826	
827	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
828	      if (ret != 0)
829	        {
830	          printf("[xiaozhi] recv: ws_recv failed: %d\n", ret);
831	          app->ws_connected = false;
832	          app->ws_dead = true;
833	          break;
834	        }
835	
836	      if (is_binary)
837	        {
838	          /* Server TTS Opus frame -> feed to player. */
839	          if (app->tts_playing)
840	            {
841	              xiaozhi_audio_write_opus(app->audio, payload, plen);
842	            }
843	          continue;
844	        }
845	
846	      /* Text frame: parse JSON. */
847	      {
848	        char *json = malloc(plen + 1);
849	        if (json == NULL)
850	          {
851	            continue;
852	          }
853	
854	        memcpy(json, payload, plen);
855	        json[plen] = '\0';
856	
857	        cJSON *root = cJSON_Parse(json);
858	        if (root != NULL)
859	          {
860	            printf("[xiaozhi] <<< recv: %s\n", json);
861	
862	            cJSON *type = cJSON_GetObjectItem(root, "type");
863	            const char *tstr = cJSON_IsString(type) ?
864	              type->valuestring : "";
865	
866	            if (strcmp(tstr, "stt") == 0)
867	              {
868	                cJSON *text = cJSON_GetObjectItem(root, "text");
869	                const char *s = text ? text->valuestring : "?";
870	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
871	                app->got_stt = true;
872	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
873	              }
874	            else if (strcmp(tstr, "llm") == 0)
875	              {
876	                cJSON *text = cJSON_GetObjectItem(root, "text");
877	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
878	                       text ? text->valuestring : "?");
879	              }
880	            else if (strcmp(tstr, "tts") == 0)
881	              {
882	                cJSON *state = cJSON_GetObjectItem(root, "state");
883	                const char *sstr = cJSON_IsString(state) ?
884	                  state->valuestring : "";
885	
886	                if (strcmp(sstr, "start") == 0)
887	                  {
888	                    pthread_mutex_lock(&s_ui_mutex);
889	                    app->tts_playing = true;
890	                    app->state = XZ_STATE_PLAYING;
891	                    pthread_mutex_unlock(&s_ui_mutex);
892	                    xiaozhi_audio_start_playback(app->audio);
893	                    printf("[xiaozhi] <<< TTS start\n");
894	                  }
895	                else if (strcmp(sstr, "stop") == 0)
896	                  {
897	                    app->tts_playing = false;
898	                    printf("[xiaozhi] <<< TTS stop\n");
899	                    xiaozhi_audio_stop_playback(app->audio);
900	                    /* End of this turn's playback. The dialog-round thread
901	                     * (if waiting) will notice tts_playing went false. */
902	                  }
903	                else if (strcmp(sstr, "sentence_start") == 0)
904	                  {
905	                    cJSON *text = cJSON_GetObjectItem(root, "text");
906	                    const char *s = text ? text->valuestring : "?";
907	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
908	                    app->tts_sentences++;
909	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
910	                  }
911	              }
912	            else if (strcmp(tstr, "goodbye") == 0)
913	              {
914	                printf("[xiaozhi] <<< goodbye\n");
915	                app->ws_connected = false;
916	                app->ws_dead = true;
917	                cJSON_Delete(root);
918	                free(json);
919	                break;
920	              }
921	            else if (strcmp(tstr, "mcp") == 0)
922	              {
923	                cJSON *payload_obj = cJSON_GetObjectItem(root, "payload");
924	                cJSON *method = payload_obj ?
925	                  cJSON_GetObjectItem(payload_obj, "method") : NULL;
926	                bool is_tools_list = cJSON_IsString(method) &&
927	                  strcmp(method->valuestring, "tools/list") == 0;
928	
929	                mcp_server_handle_message(root, mcp_send_json);
930	
931	                if (is_tools_list)
932	                  {
933	                    printf("[xiaozhi] MCP handshake done\n");
934	                    app->mcp_done = true;
935	                  }
936	              }
937	            else if (strcmp(tstr, "hello") == 0)
938	              {
939	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
940	                if (cJSON_IsString(sid))
941	                  {
942	                    strncpy(app->session_id, sid->valuestring,
943	                            sizeof(app->session_id) - 1);
944	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
945	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
946	                           app->session_id);
947	                  }
948	              }
949	            else
950	              {
951	                char *out = cJSON_PrintUnformatted(root);
952	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
953	                if (out)
954	                  {
955	                    free(out);
956	                  }
957	              }
958	
959	            cJSON_Delete(root);
960	          }
961	        else
962	          {
963	            printf("[xiaozhi] <<< (parse err) %.*s\n",
964	                   (int)plen, (const char *)payload);
965	          }
966	
967	        free(json);
968	      }
969	    }
970	
971	  printf("[xiaozhi] recv thread exiting\n");
972	  return NULL;
973	}
