975	/* Send the hello handshake JSON. */
976	static void send_hello(struct xiaozhi_app_s *app)
977	{
978	  cJSON *hello = cJSON_CreateObject();
979	  cJSON_AddStringToObject(hello, "type", "hello");
980	  cJSON_AddNumberToObject(hello, "version", 3);
981	  cJSON_AddStringToObject(hello, "transport", "websocket");
982	
983	  cJSON *ap = cJSON_CreateObject();
984	  cJSON_AddStringToObject(ap, "format", "opus");
985	  cJSON_AddNumberToObject(ap, "sample_rate", 16000);
986	  cJSON_AddNumberToObject(ap, "channels", 1);
987	  cJSON_AddNumberToObject(ap, "frame_duration", 60);
988	  cJSON_AddItemToObject(hello, "audio_params", ap);
989	
990	  mcp_server_add_hello_features(hello);
991	
992	  char *s = cJSON_PrintUnformatted(hello);
993	  printf("[xiaozhi] >>> hello json: %s\n", s ? s : "null");
994	  if (s)
995	    {
996	      free(s);
997	    }
998	  send_json(app, hello);
999	  cJSON_Delete(hello);

1000	}
