1002	/* Connect thread: runs once at app open. Does OTA -> wss -> hello -> MCP,
1003	 * updating the status label at each node. Then launches the background
1004	 * recv_thread and signals handshake_done so the Speak button goes live.
1005	 */
1006	static void *connect_thread(void *arg)
1007	{
1008	  struct xiaozhi_app_s *app = arg;
1009	  struct xiaozhi_ota_config_s ota;
1010	  const char *mac = XIAOZHI_MAC_DEFAULT;
1011	  char client_id[40];
1012	  pthread_t recv_tid;
1013	  int ret;
1014	
1015	  snprintf(client_id, sizeof(client_id),
1016	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
1017	
1018	  /* Init audio subsystem (creates Opus encoder). */
1019	  app->audio = xiaozhi_audio_init();
1020	  if (app->audio == NULL)
1021	    {
1022	      printf("[xiaozhi] audio init failed\n");
1023	      app->state = XZ_STATE_ERROR;
1024	      app->handshake_failed = true;
1025	      return NULL;
1026	    }
1027	
1028	  /* Init MCP tool server. */
1029	  s_mcp_app = app;
1030	  mcp_register_tools();
1031	
1032	  /* Step 1: OTA. */
1033	  pthread_mutex_lock(&s_ui_mutex);
1034	  app->state = XZ_STATE_OTA;
1035	  pthread_mutex_unlock(&s_ui_mutex);
1036	  printf("[xiaozhi] step 1: OTA\n");
1037	  ret = xiaozhi_ota_fetch(mac, &ota);
1038	  if (ret != 0)
1039	    {
1040	      printf("[xiaozhi] OTA failed: %d\n", ret);
1041	      app->state = XZ_STATE_ERROR;
1042	      app->handshake_failed = true;
1043	      return NULL;
1044	    }
1045	
1046	  /* Step 2: wss connect (TLS + ws upgrade). */
1047	  pthread_mutex_lock(&s_ui_mutex);
1048	  app->state = XZ_STATE_CONNECT;
1049	  pthread_mutex_unlock(&s_ui_mutex);
1050	  printf("[xiaozhi] step 2: wss connect\n");
1051	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
1052	                           client_id);
1053	  if (ret != 0)
1054	    {
1055	      printf("[xiaozhi] ws connect failed: %d\n", ret);
1056	      app->state = XZ_STATE_ERROR;
1057	      app->handshake_failed = true;
1058	      return NULL;
1059	    }
1060	
1061	  app->ws_connected = true;
1062	
1063	  /* Launch the background receive thread BEFORE sending hello, so we don't
1064	   * miss the server's hello/MCP response. */
1065	  pthread_attr_t attr;
1066	  pthread_attr_init(&attr);
1067	  pthread_attr_setstacksize(&attr, 32768);
1068	  ret = pthread_create(&recv_tid, &attr, recv_thread, app);
1069	  pthread_attr_destroy(&attr);
1070	  if (ret != 0)
1071	    {
1072	      printf("[xiaozhi] recv thread create failed: %d\n", ret);
1073	      app->state = XZ_STATE_ERROR;
1074	      app->handshake_failed = true;
1075	      return NULL;
1076	    }
1077	
1078	  /* Step 3: send hello. recv_thread will capture session_id. */
1079	  printf("[xiaozhi] step 3: send hello\n");
1080	  send_hello(app);
1081	
1082	  /* Wait for the server hello response (session_id). */
1083	  int waited = 0;
1084	  while (app->session_id[0] == '\0' && app->ws_connected && waited < 8000)
1085	    {
1086	      usleep(100 * 1000);
1087	      waited += 100;
1088	    }
1089	  if (app->session_id[0] == '\0')
1090	    {
1091	      printf("[xiaozhi] no session_id after hello, abort\n");
1092	      app->ws_connected = false;
1093	      app->ws_dead = true;
1094	      app->state = XZ_STATE_ERROR;
1095	      app->handshake_failed = true;
1096	      return NULL;
1097	    }
1098	
1099	  /* Step 3b: wait for MCP initialize (tools/list). */
1100	  printf("[xiaozhi] step 3b: wait for MCP initialize\n");
1101	  waited = 0;
1102	  while (!app->mcp_done && app->ws_connected && waited < 5000)
1103	    {
1104	      usleep(100 * 1000);
1105	      waited += 100;
1106	    }
1107	
1108	  if (!app->ws_connected)
1109	    {
1110	      printf("[xiaozhi] connection lost during handshake, abort\n");
1111	      app->ws_dead = true;
1112	      app->state = XZ_STATE_ERROR;
1113	      app->handshake_failed = true;
1114	      return NULL;
1115	    }
1116	
1117	  /* Handshake complete — Speak button goes live. */
1118	  pthread_mutex_lock(&s_ui_mutex);
1119	  app->handshake_done = true;
1120	  app->state = XZ_STATE_READY;
1121	  pthread_mutex_unlock(&s_ui_mutex);
1122	  printf("[xiaozhi] === handshake done, Speak ready ===\n");
1123	
1124	  /* Keep this thread alive so recv_thread (detached by stack) persists.
1125	   * It simply waits — the recv_thread does all the work. When the app
1126	   * exits (xiaozhi_voice_delete), ws_connected is cleared and both wind down.
1127	   */
1128	  while (app->ws_connected)
1129	    {
1130	      usleep(200 * 1000);
1131	    }
1132	
1133	  printf("[xiaozhi] connect thread: connection down, cleaning up\n");
1134	  if (app->tts_playing)
1135	    {
1136	      xiaozhi_audio_stop_playback(app->audio);
1137	    }
1138	  xiaozhi_audio_deinit(app->audio);
1139	  xiaozhi_ws_close(&app->ws);
1140	
1141	  return NULL;
1142	}
1143	
1144	/* Dialog-round thread: triggered by Speak release.
1145	 * Joins the capture thread (finishes buffering), runs the validity check
1146	 * (min duration + RMS), and if valid: sends listen:start -> drains buffered
1147	 * opus frames -> listen:stop, then waits for the server stt/tts playback.
1148	 * The persistent recv_thread handles the incoming stt/tts frames.
1149	 */
1150	static void *dialog_round_thread(void *arg)
1151	{
1152	  struct xiaozhi_app_s *app = arg;
1153	
1154	  /* Signal the capture thread to stop. It may be blocked inside
1155	   * xiaozhi_audio_read_opus() on media_recorder_read_data(); we must
1156	   * stop the recorder first so that read unblocks, THEN join.
1157	   * But wait for start_capture to finish first — stopping before the
1158	   * recorder is open would race the capture thread's setup. */
1159	  app->capture_stop = true;
1160	  app->capturing = false;
1161	  int spin = 0;
1162	  while (!app->capture_started && spin < 3000)
1163	    {
1164	      usleep(10 * 1000);
1165	      spin += 10;
1166	    }
1167	
1168	  xiaozhi_audio_stop_capture(app->audio);
1169	
1170	  if (app->capture_tid_valid)
1171	    {
1172	      pthread_join(app->capture_tid, NULL);
1173	      app->capture_tid_valid = false;
1174	    }
1175	  app->capture_started = false;
1176	
1177	  uint32_t dur = lv_tick_get() - app->speak_press_ms;
1178	  int rms = xiaozhi_audio_rms_get(app->audio);
1179	  printf("[xiaozhi] round: dur=%ums rms=%d frames=%d\n",
1180	         dur, rms, app->frame_buf_cnt);
1181	
1182	  /* Validity check: min duration + actual speech. */
1183	  if (dur < XZ_MIN_INPUT_MS)
1184	    {
1185	      printf("[xiaozhi] round: too short (%u<%d), discard\n",
1186	             dur, XZ_MIN_INPUT_MS);
1187	      goto back_to_ready;
1188	    }
1189	
1190	  if (rms < XZ_SPEAK_RMS_THRESH)
1191	    {
1192	      printf("[xiaozhi] round: silent (rms=%d<%d), discard\n",
1193	             rms, XZ_SPEAK_RMS_THRESH);
1194	      goto back_to_ready;
1195	    }
1196	
1197	  /* Valid input — send listen:start, drain buffered audio, listen:stop. */
1198	  if (!app->ws_connected)
1199	    {
1200	      printf("[xiaozhi] round: connection lost before send\n");
1201	      goto back_to_ready;
1202	    }
1203	
1204	  pthread_mutex_lock(&s_ui_mutex);
1205	  app->state = XZ_STATE_LISTENING;
1206	  pthread_mutex_unlock(&s_ui_mutex);
1207	  printf("[xiaozhi] round: listen start, session_id=%s\n", app->session_id);
1208	
1209	  {
1210	    cJSON *listen = cJSON_CreateObject();
1211	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
1212	    cJSON_AddStringToObject(listen, "type", "listen");
1213	    cJSON_AddStringToObject(listen, "state", "start");
1214	    cJSON_AddStringToObject(listen, "mode", "manual");
1215	    send_json(app, listen);
1216	    cJSON_Delete(listen);
1217	  }
1218	
1219	  drain_buffer_to_server(app);
1220	
1221	  {
1222	    cJSON *stop = cJSON_CreateObject();
1223	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
1224	    cJSON_AddStringToObject(stop, "type", "listen");
1225	    cJSON_AddStringToObject(stop, "state", "stop");
1226	    send_json(app, stop);
1227	    cJSON_Delete(stop);
1228	  }
1229	
1230	  /* Wait for STT + TTS playback. recv_thread flips tts_playing true (tts
1231	   * start) then false (tts stop). */
1232	  pthread_mutex_lock(&s_ui_mutex);
1233	  app->state = XZ_STATE_THINKING;
1234	  pthread_mutex_unlock(&s_ui_mutex);
1235	  printf("[xiaozhi] round: wait stt/tts\n");
1236	
1237	  int waited = 0;
1238	  while (!app->tts_playing && app->ws_connected && waited < 15000)
1239	    {
1240	      usleep(100 * 1000);
1241	      waited += 100;
1242	    }
1243	  while (app->tts_playing && app->ws_connected)
1244	    {
1245	      usleep(100 * 1000);
1246	    }
1247	
1248	back_to_ready:
1249	  /* Round done — back to ready (if still connected). */
1250	  pthread_mutex_lock(&s_ui_mutex);
1251	  if (app->ws_connected)
1252	    {
1253	      app->state = XZ_STATE_READY;
1254	    }
1255	  else
1256	    {
1257	      app->state = XZ_STATE_ERROR;
1258	    }
1259	  /* Clear per-round display state for the next turn. */
1260	  app->capturing = false;
1261	  app->capture_stop = false;
1262	  app->got_stt = false;
1263	  app->frame_buf_cnt = 0;
1264	  memset(app->stt_text, 0, sizeof(app->stt_text));
1265	  memset(app->tts_text, 0, sizeof(app->tts_text));
1266	  pthread_mutex_unlock(&s_ui_mutex);
1267	
1268	  printf("[xiaozhi] === round done: stt=%s tts=%d ===\n",
1269	         app->got_stt ? "yes" : "no", app->tts_sentences);
1270	
1271	  app->dialog_running = false;
1272	  return NULL;
1273	}
