1275	/* Speak button event handler.
1276	 * PRESSED: start capturing into the frame buffer (background capture thread).
1277	 * RELEASED: stop capturing and launch the dialog-round thread, which joins
1278	 *           the capture, runs the validity check, and sends to the server.
1279	 */
1280	static void speak_btn_event_cb(lv_event_t *e)
1281	{
1282	  struct xiaozhi_app_s *app = &g_app;
1283	  lv_event_code_t code = lv_event_get_code(e);
1284	
1285	  if (!app->handshake_done || app->ws_dead)
1286	    {
1287	      printf("[xiaozhi] speak: not ready yet\n");
1288	      return;
1289	    }
1290	
1291	  if (app->dialog_running)
1292	    {
1293	      return;   /* a round is in progress */
1294	    }
1295	
1296	  if (code == LV_EVENT_PRESSED)
1297	    {
1298	      printf("[xiaozhi] speak PRESSED: start capture\n");
1299	      app->speak_press_ms = lv_tick_get();
1300	      app->capturing = true;
1301	      app->capture_stop = false;
1302	      app->frame_buf_cnt = 0;
1303	      xiaozhi_audio_rms_reset(app->audio);
1304	
1305	      pthread_mutex_lock(&s_ui_mutex);
1306	      app->state = XZ_STATE_LISTENING;
1307	      pthread_mutex_unlock(&s_ui_mutex);
1308	
1309	      /* Launch the capture thread — it calls start_capture (which blocks on
1310	       * the SMF codec ~150ms) and then buffers opus frames. Doing start_capture
1311	       * here on the LVGL thread would stall the touch indev and drop the press. */
1312	      pthread_attr_t attr;
1313	      pthread_attr_init(&attr);
1314	      pthread_attr_setstacksize(&attr, 32768);
1315	      int ret = pthread_create(&app->capture_tid, &attr, capture_thread, app);
1316	      pthread_attr_destroy(&attr);
1317	      if (ret != 0)
1318	        {
1319	          printf("[xiaozhi] speak: capture thread failed: %d\n", ret);
1320	          app->capturing = false;
1321	          pthread_mutex_lock(&s_ui_mutex);
1322	          app->state = XZ_STATE_READY;
1323	          pthread_mutex_unlock(&s_ui_mutex);
1324	        }
1325	      app->capture_tid_valid = true;
1326	    }
1327	  else if (code == LV_EVENT_RELEASED)
1328	    {
1329	      if (!app->capturing)
1330	        {
1331	          return;
1332	        }
1333	
1334	      printf("[xiaozhi] speak RELEASED\n");
1335	
1336	      /* Tell the capture thread to stop, then hand off to the dialog-round
1337	       * thread (which joins the capture thread and does the validity check
1338	       * + send). All blocking work happens off the LVGL thread. */
1339	      app->capture_stop = true;
1340	      app->capturing = false;
1341	
1342	      app->dialog_running = true;
1343	      pthread_mutex_lock(&s_ui_mutex);
1344	      app->state = XZ_STATE_THINKING;
1345	      pthread_mutex_unlock(&s_ui_mutex);
1346	
1347	      pthread_attr_t attr;
1348	      pthread_attr_init(&attr);
1349	      pthread_attr_setstacksize(&attr, 32768);
1350	      int ret = pthread_create(NULL, &attr, dialog_round_thread, app);
1351	      pthread_attr_destroy(&attr);
1352	      if (ret != 0)
1353	        {
1354	          printf("[xiaozhi] dialog round thread create failed: %d\n", ret);
1355	          if (app->capture_tid_valid)
1356	            {
1357	              pthread_join(app->capture_tid, NULL);
1358	              app->capture_tid_valid = false;
1359	            }
1360	          xiaozhi_audio_stop_capture(app->audio);
1361	          app->dialog_running = false;
1362	          pthread_mutex_lock(&s_ui_mutex);
1363	          app->state = XZ_STATE_READY;
1364	          pthread_mutex_unlock(&s_ui_mutex);
1365	        }
1366	    }
1367	}
