1476	/* Refresh the LVGL screen from the shared app state.
1477	 * NOTE: This function performs LVGL operations and should only be called
1478	 * from LVGL timer callbacks (which run in the LVGL thread context).
1479	 * Do NOT call this from worker threads directly.
1480	 */
1481	static void ui_refresh(struct xiaozhi_app_s *app)
1482	{
