1513	            {
1514	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 280);
1515	            }
1516	          if (app->tts_label != NULL)
1517	            {
1518	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 310);
1519	            }
1520	        }
1521	      else if (app->state == XZ_STATE_THINKING)
1522	        {
