1542	            {
1543	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 270);
1544	            }
1545	        }
1546	      else if (app->state == XZ_STATE_PLAYING)
1547	        {
1548	          /* Playing状态：只隐藏label背景 */
1549	          if (s_stt_caption != NULL)
1550	            {
1551	              lv_obj_align(s_stt_caption, LV_ALIGN_TOP_MID, 0, 180);
1552	              lv_obj_set_style_bg_opa(s_stt_caption, LV_OPA_TRANSP, 0);
1553	            }
1554	          if (app->stt_label != NULL)
1555	            {
1556	              lv_obj_align(app->stt_label, LV_ALIGN_TOP_MID, 0, 210);
1557	              lv_obj_set_style_bg_opa(app->stt_label, LV_OPA_TRANSP, 0);
1558	            }
1559	          if (s_tts_caption != NULL)
1560	            {
1561	              lv_obj_align(s_tts_caption, LV_ALIGN_TOP_MID, 0, 270);
1562	              lv_obj_set_style_bg_opa(s_tts_caption, LV_OPA_TRANSP, 0);
1563	            }
1564	          if (app->tts_label != NULL)
1565	            {
1566	              lv_obj_align(app->tts_label, LV_ALIGN_TOP_MID, 0, 300);
1567	              lv_obj_set_style_bg_opa(app->tts_label, LV_OPA_TRANSP, 0);
1568	            }
1569	        }
1570	      else
1571	        {
1572	          /* 其他状态：恢复默认位置 */
1573	          if (s_stt_caption != NULL)
