1691	
1692	void xiaozhi_voice_start(void)
1693	{
1694	  LV_LOG_USER("==================xiaozhi_voice_start==================");
1695	
1696	  /* 如果已经初始化过，直接显示 */
1697	  if (xiaozhi_container != NULL)
1698	    {
1699	      /* 显示容器 */
1700	      lv_obj_clear_flag(xiaozhi_container, LV_OBJ_FLAG_HIDDEN);
1701	      return;
1702	    }
1703	
1704	  /* 初始化应用状态 */
1705	  memset(&g_app, 0, sizeof(g_app));
1706	  g_app.state = XZ_STATE_BOOT;
1707	
1708	  /* 初始化字体管理器（加载中文字体） */
1709	  font_manager_init();
1710	
1711	  /* 创建UI */
1712	  ui_create(&g_app);
1713	
1714	  /* 启动UI刷新定时器，每100ms刷新一次 */
1715	  if (ui_refresh_timer == NULL)
1716	    {
1717	      ui_refresh_timer = lv_timer_create(ui_refresh_timer_cb, 100, NULL);
1718	    }
1719	
1720	  /* Launch the connect thread: runs OTA -> wss -> hello -> MCP in the
1721	   * background. The status label updates at each node; when done, the
1722	   * ui_refresh timer will enable the Speak button automatically. */
1723	  pthread_attr_t attr;
1724	  pthread_attr_init(&attr);
1725	  pthread_attr_setstacksize(&attr, 65536);
1726	  int ret = pthread_create(NULL, &attr, connect_thread, &g_app);
1727	  pthread_attr_destroy(&attr);
1728	  if (ret != 0)
1729	    {
1730	      printf("[xiaozhi] connect thread create failed: %d\n", ret);
1731	      g_app.state = XZ_STATE_ERROR;
1732	      g_app.handshake_failed = true;
1733	    }
1734	}
1735	
1736	void xiaozhi_voice_delete(void)
1737	{
1738	  /* Signal worker threads to stop, then let connect_thread clean up the
1739	   * wss connection + audio. Closing ws_connected causes recv_thread to
1740	   * exit, which in turn lets connect_thread's wait-loop finish and tear
1741	   * down the socket + audio. */
1742	  g_app.ws_connected = false;
1743	  g_app.capturing = false;
1744	  g_app.capture_stop = true;
1745	
1746	  /* If a capture thread is mid-flight (Speak was held on exit), wait for its
1747	   * start_capture to finish, then stop the recorder so its blocking read
1748	   * unblocks, then join — so it doesn't touch freed audio/LVGL state. */
1749	  if (g_app.capture_tid_valid)
1750	    {
1751	      int spin = 0;
1752	      while (!g_app.capture_started && spin < 3000)
1753	        {
1754	          usleep(10 * 1000);
1755	          spin += 10;
1756	        }
1757	      if (g_app.audio != NULL)
1758	        {
1759	          xiaozhi_audio_stop_capture(g_app.audio);
1760	        }
1761	      pthread_join(g_app.capture_tid, NULL);
1762	      g_app.capture_tid_valid = false;
1763	      g_app.capture_started = false;
1764	    }
1765	  else if (g_app.audio != NULL)
1766	    {
1767	      xiaozhi_audio_stop_capture(g_app.audio);
1768	    }
1769	
1770	  /* Give the background threads a moment to wind down before we destroy
1771	   * the LVGL objects they may still be touching indirectly. */
1772	  usleep(150 * 1000);
1773	
1774	  /* 停止所有动画 */
1775	  wave_anim_stop();
1776	  think_anim_stop();
1777	
1778	  /* 停止UI刷新定时器 */
1779	  if (ui_refresh_timer != NULL)
1780	    {
1781	      lv_timer_delete(ui_refresh_timer);
1782	      ui_refresh_timer = NULL;
1783	    }
1784	
1785	  /* 删除容器 */
1786	  if (xiaozhi_container != NULL)
1787	    {
1788	      lv_obj_del(xiaozhi_container);
1789	      xiaozhi_container = NULL;
1790	    }
1791	
1792	  /* 重置静态标签指针 */
1793	  s_stt_caption = NULL;
1794	  s_tts_caption = NULL;
1795	
1796	  /* 重置应用状态 */
1797	  memset(&g_app, 0, sizeof(g_app));
1798	}
