1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ws.c
3	 *
4	 * A lightweight WebSocket-over-TLS (wss) client.
5	 *   - TLS layer: mbedtls (pattern borrowed from packages/demos/mimo)
6	 *   - WebSocket framing: RFC 6455
7	 *
8	 * Supports the subset needed by the xiaozhi protocol:
9	 *   - client->server text(0x1) and binary(0x2) frames, masked
10	 *   - server->client text/binary/close frames, unmasked
11	 *   - payload lengths up to 65535 (16-bit length); 64-bit length not needed
12	 *     here (Opus frames and JSON messages are short)
13	 *
14	 * SPDX-License-Identifier: Apache-2.0
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <stdio.h>
20	#include <string.h>
21	#include <stdlib.h>
22	#include <errno.h>
23	#include <unistd.h>
24	#include <netdb.h>
25	#include <netinet/in.h>
26	#include <arpa/inet.h>
27	#include <sys/socket.h>
28	#include <sys/time.h>
29	
30	#include "xiaozhi_ws.h"
31	
32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	#define WS_RXBUF_SIZE  4096
37	
38	/* WebSocket opcodes */
39	#define WS_OPCODE_CONTINUATION 0x0
40	#define WS_OPCODE_TEXT         0x1
41	#define WS_OPCODE_BINARY       0x2
42	#define WS_OPCODE_CLOSE        0x8
43	#define WS_OPCODE_PING         0x9
44	#define WS_OPCODE_PONG         0xa
45	
46	#define WS_FIN_BIT   0x80
47	#define WS_MASK_BIT  0x80
48	
49	/* Largest single payload buffered for masking before a TLS write.
50	 * Covers Opus frames (<= ~400B); large JSON frames spill to a slow path. */
51	#define XZ_WS_PAYLOAD_MAX 1024
52	
53	/****************************************************************************
54	 * Private Functions - TLS
55	 ****************************************************************************/
56	
57	/* BIO send: write to the plain TCP fd. */
58	static int ws_bio_send(void *ctx, const unsigned char *buf, size_t len)
59	{
60	  int fd = *(int *)ctx;
61	  ssize_t ret = send(fd, buf, len, 0);
62	  if (ret < 0)
63	    {
64	      return -EIO;
65	    }
66	
67	  return (int)ret;
68	}
69	
70	/* BIO recv: read from the plain TCP fd. */
71	static int ws_bio_recv(void *ctx, unsigned char *buf, size_t len)
72	{
73	  int fd = *(int *)ctx;
74	  ssize_t ret = recv(fd, buf, len, 0);
75	  if (ret < 0)
76	    {
77	      return -EIO;
78	    }
79	
80	  if (ret == 0)
81	    {
82	      return MBEDTLS_ERR_SSL_WANT_READ;
83	    }
84	
85	  return (int)ret;
86	}
87	
88	static int ws_tls_init(struct xiaozhi_ws_s *ws)
89	{
90	  int ret;
91	
92	  mbedtls_ssl_init(&ws->ssl);
93	  mbedtls_ssl_config_init(&ws->conf);
94	  mbedtls_entropy_init(&ws->entropy);
95	  mbedtls_ctr_drbg_init(&ws->ctr_drbg);
96	
97	  ret = mbedtls_ctr_drbg_seed(&ws->ctr_drbg, mbedtls_entropy_func,
98	                              &ws->entropy,
99	                              (const unsigned char *)"xiaozhi", 7);
100	  if (ret != 0)
101	    {
102	      printf("[xiaozhi] drbg seed failed: -0x%x\n", -ret);
103	      return -EIO;
104	    }
105	
106	  ret = mbedtls_ssl_config_defaults(&ws->conf, MBEDTLS_SSL_IS_CLIENT,
107	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
108	                                    MBEDTLS_SSL_PRESET_DEFAULT);
109	  if (ret != 0)
110	    {
111	      printf("[xiaozhi] ssl config defaults failed: -0x%x\n", -ret);
112	      return -EIO;
113	    }
114	
115	  /* Skip server cert verification for embedded use.
116	   * For production, configure CA certs via mbedtls_ssl_conf_ca_chain().
117	   */
118	  mbedtls_ssl_conf_authmode(&ws->conf, MBEDTLS_SSL_VERIFY_NONE);
119	  mbedtls_ssl_conf_rng(&ws->conf, mbedtls_ctr_drbg_random, &ws->ctr_drbg);
120	
121	  ret = mbedtls_ssl_setup(&ws->ssl, &ws->conf);
122	  if (ret != 0)
123	    {
124	      printf("[xiaozhi] ssl setup failed: -0x%x\n", -ret);
125	      return -EIO;
126	    }
127	
128	  return 0;
129	}
130	
131	/* Connect TCP, do TLS handshake over it. */
132	static int ws_tls_connect(struct xiaozhi_ws_s *ws, const char *host,
133	                         const char *port)
134	{
135	  struct hostent *he;
136	  struct sockaddr_in server;
137	  int portnum = atoi(port);
138	  int ret;
139	
140	  printf("[xiaozhi] TLS connecting to %s:%s\n", host, port);
141	
142	  he = gethostbyname(host);
143	  if (he == NULL)
144	    {
145	      printf("[xiaozhi] DNS resolve failed for %s\n", host);
146	      return -EIO;
147	    }
148	
149	  ws->fd = socket(AF_INET, SOCK_STREAM, 0);
150	  if (ws->fd < 0)
151	    {
152	      printf("[xiaozhi] socket() failed: %d\n", errno);
153	      return -EIO;
154	    }
155	
156	  memset(&server, 0, sizeof(server));
157	  server.sin_family = AF_INET;
158	  server.sin_port   = htons(portnum);
159	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
160	
161	  printf("[xiaozhi] TCP connect to %s:%d\n",
162	         inet_ntoa(server.sin_addr), portnum);
163	
164	  if (connect(ws->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
165	    {
166	      printf("[xiaozhi] TCP connect failed: %d\n", errno);
167	      close(ws->fd);
168	      ws->fd = -1;
169	      return -EIO;
170	    }
171	
172	  /* Set socket send/recv timeouts to prevent blocking forever */
173	
174	  struct timeval tv;
175	  tv.tv_sec = 10;
176	  tv.tv_usec = 0;
177	  setsockopt(ws->fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
178	  setsockopt(ws->fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
179	
180	  printf("[xiaozhi] TCP connected, starting TLS handshake\n");
181	
182	  ret = mbedtls_ssl_set_hostname(&ws->ssl, host);
183	  if (ret != 0)
184	    {
185	      printf("[xiaozhi] set hostname failed: -0x%x\n", -ret);
186	      goto err;
187	    }
188	
189	  mbedtls_ssl_set_bio(&ws->ssl, &ws->fd, ws_bio_send, ws_bio_recv, NULL);
190	
191	  int hs_retries = 0;
192	  while ((ret = mbedtls_ssl_handshake(&ws->ssl)) != 0)
193	    {
194	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
195	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
196	        {
197	          printf("[xiaozhi] TLS handshake failed: -0x%x\n", -ret);
198	          goto err;
199	        }
200	      if (++hs_retries >= 20)
201	        {
202	          printf("[xiaozhi] TLS handshake timeout\n");
203	          goto err;
204	        }
205	      usleep(500000);
206	    }
207	
208	  printf("[xiaozhi] TLS handshake complete\n");
209	  return 0;
210	
211	err:
212	  close(ws->fd);
213	  ws->fd = -1;
214	  return -EIO;
215	}
216	
217	/****************************************************************************
218	 * Private Functions - TLS read/write wrappers
219	 ****************************************************************************/
220	
221	/* Send all bytes over TLS. Returns 0 on success, -errno on failure. */
222	static int ws_tls_write_all(struct xiaozhi_ws_s *ws,
223	                            const uint8_t *buf, size_t len)
224	{
225	  size_t written = 0;
226	  while (written < len)
227	    {
228	      int ret = mbedtls_ssl_write(&ws->ssl, buf + written, len - written);
229	      if (ret == MBEDTLS_ERR_SSL_WANT_WRITE ||
230	          ret == MBEDTLS_ERR_SSL_WANT_READ)
231	        {
232	          continue;
233	        }
234	
235	      if (ret <= 0)
236	        {
237	          printf("[xiaozhi] tls write error: -0x%x\n", -ret);
238	          return -EIO;
239	        }
240	
241	      written += ret;
242	    }
243	
244	  return 0;
245	}
246	
247	/* Read exactly n bytes over TLS into buf. Returns 0 on success, -errno. */
248	static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
249	{
250	  size_t got = 0;
251	  while (got < n)
252	    {
253	      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
254	      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
255	          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
256	        {
257	          continue;
258	        }
259	
260	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
261	        {
262	          printf("[xiaozhi] tls peer closed during read\n");
263	          return -ECONNRESET;
264	        }
265	
266	      if (ret < 0)
267	        {
268	          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
269	          return -EIO;
270	        }
271	
272	      got += ret;
273	    }
274	
275	  return 0;
276	}
277	
278	/****************************************************************************
279	 * Private Functions - WebSocket framing
280	 ****************************************************************************/
281	
282	/* Generate a random 4-byte masking key. mbedtls_ctr_drbg_random is used as
283	 * a random source (no Date.now/random needed).
284	 */
285	static void ws_make_mask(uint8_t mask[4], struct xiaozhi_ws_s *ws)
286	{
287	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, mask, 4);
288	}
289	
290	/* Send one client->server frame (masked). */
291	static int ws_send_frame(struct xiaozhi_ws_s *ws, uint8_t opcode,
292	                         const uint8_t *data, size_t len)
293	{
294	  uint8_t hdr[14];
295	  size_t hdrlen;
296	  uint8_t mask[4];
297	  int ret;
298	
299	  hdr[0] = WS_FIN_BIT | opcode;
300	
301	  if (len <= 125)
302	    {
303	      hdr[1] = WS_MASK_BIT | (uint8_t)len;
304	      hdrlen = 2;
305	    }
306	  else if (len <= 65535)
307	    {
308	      hdr[1] = WS_MASK_BIT | 126;
309	      hdr[2] = (len >> 8) & 0xff;
310	      hdr[3] = len & 0xff;
311	      hdrlen = 4;
312	    }
313	  else
314	    {
315	      /* 64-bit length path. Opus/JSON frames are never this large, but
316	       * implement for completeness.
317	       */
318	      hdr[1] = WS_MASK_BIT | 127;
319	      uint64_t l = len;
320	      hdr[2] = 0; hdr[3] = 0; hdr[4] = 0; hdr[5] = 0;
321	      hdr[6] = (l >> 24) & 0xff;
322	      hdr[7] = (l >> 16) & 0xff;
323	      hdr[8] = (l >> 8) & 0xff;
324	      hdr[9] = l & 0xff;
325	      hdrlen = 10;
326	    }
327	
328	  ret = ws_tls_write_all(ws, hdr, hdrlen);
329	  if (ret != 0)
330	    {
331	      return ret;
332	    }
333	
334	  /* Masking key + masked payload. */
335	  ws_make_mask(mask, ws);
336	  ret = ws_tls_write_all(ws, mask, 4);
337	  if (ret != 0)
338	    {
339	      return ret;
340	    }
341	
342	  if (len > 0)
343	    {
344	      /* Mask the whole payload into a local buffer, then send in a single
345	       * TLS write. Doing one mbedtls_ssl_write() per byte (the old code)
346	       * made every Opus frame cost hundreds of syscalls and was the main
347	       * cause of mic DMA buffer overruns / dropped frames. */
348	      uint8_t masked[XZ_WS_PAYLOAD_MAX];
349	      size_t cap = len < sizeof(masked) ? len : sizeof(masked);
350	
351	      for (size_t i = 0; i < cap; i++)
352	        {
353	          masked[i] = data[i] ^ mask[i & 3];
354	        }
355	
356	      ret = ws_tls_write_all(ws, masked, cap);
357	      if (ret != 0)
358	        {
359	          return ret;
360	        }
361	
362	      /* Payloads larger than the local cap (only large JSON frames) are
363	       * sent in a second chunk. Opus frames never hit this path. */
364	      if (cap < len)
365	        {
366	          uint8_t one;
367	          for (size_t i = cap; i < len; i++)
368	            {
369	              one = data[i] ^ mask[i & 3];
370	              ret = ws_tls_write_all(ws, &one, 1);
371	              if (ret != 0)
372	                {
373	                  return ret;
374	                }
375	            }
376	        }
377	    }
378	
379	  return 0;
380	}
