382	/****************************************************************************
383	 * Public Functions
384	 ****************************************************************************/
385	
386	int xiaozhi_ws_connect(struct xiaozhi_ws_s *ws, const char *ws_url,
387	                       const char *token, const char *device_id,
388	                       const char *client_id)
389	{
390	  char host[128];
391	  char path[256];
392	  char pathwithtok[320];   /* path + ?token=<token> for the GET line */
393	  char portstr[8];
394	  const char *p;
395	  const char *hoststart;
396	  const char *hostend;
397	  const char *pathstart;
398	  int port = 443;
399	  int ret;
400	  uint8_t wskey[16];

400	  uint8_t wskey[16];
401	  char req[768];
402	
403	  memset(ws, 0, sizeof(*ws));
404	  ws->fd = -1;
405	
406	  /* Parse "wss://host[:port]/path..." */
407	  if (strncmp(ws_url, "wss://", 6) != 0)
408	    {
409	      printf("[xiaozhi] ws url must be wss://: %s\n", ws_url);
410	      return -EINVAL;
411	    }
412	
413	  hoststart = ws_url + 6;
414	  pathstart = strchr(hoststart, '/');
415	  hostend   = pathstart ? pathstart : hoststart + strlen(hoststart);
416	
417	  /* Detect port in host portion */
418	  p = memchr(hoststart, ':', hostend - hoststart);
419	  if (p != NULL)
420	    {
421	      size_t hlen = p - hoststart;
422	      memcpy(host, hoststart, hlen);
423	      host[hlen] = '\0';
424	      port = atoi(p + 1);
425	    }
426	  else
427	    {
428	      size_t hlen = hostend - hoststart;
429	      memcpy(host, hoststart, hlen);
430	      host[hlen] = '\0';
431	    }
432	
433	  snprintf(portstr, sizeof(portstr), "%d", port);
434	
435	  if (pathstart)
436	    {
437	      snprintf(path, sizeof(path), "%s", pathstart);
438	    }
439	  else
440	    {
441	      path[0] = '/'; path[1] = '\0';
442	    }
443	
444	  /* The xiaozhi server expects the token both as a query string on the GET
445	   * line (?token=<token>) and as an Authorization: Bearer ***REDACTED*** The
446	   * working Python probe builds "{ws_url}?token={ws_token}". Append it
447	   * here when the server's URL doesn't already carry one.
448	   */
449	  if (token != NULL && token[0] != '\0' && strchr(path, '?') == NULL)
450	    {
451	      snprintf(pathwithtok, sizeof(pathwithtok), "%s?token=%s", path, token);
452	    }
453	  else
454	    {
455	      snprintf(pathwithtok, sizeof(pathwithtok), "%s", path);
456	    }
457	
458	  printf("[xiaozhi] ws host=%s port=%d path=%s token=%s\n",
459	         host, port, pathwithtok, token);
460	
461	  /* Allocate rx buffer. */
462	  ws->rxbuf_cap = WS_RXBUF_SIZE;
463	  ws->rxbuf = malloc(ws->rxbuf_cap);
464	  if (ws->rxbuf == NULL)
465	    {
466	      return -ENOMEM;
467	    }
468	
469	  /* TLS init + connect. */
470	  ret = ws_tls_init(ws);
471	  if (ret != 0)
472	    {
473	      return ret;
474	    }
475	
476	  ret = ws_tls_connect(ws, host, portstr);
477	  if (ret != 0)
478	    {
479	      return ret;
480	    }
481	
482	  /* WebSocket HTTP Upgrade handshake. */
483	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, wskey, 16);
484	
485	  /* Build Sec-WebSocket-Key (base64 of 16 random bytes). We use a tiny
486	   * base64 encoder below.
487	   */
488	  char wskey_b64[32];
489	  {
490	    const char b64[] =
491	      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
492	    int o = 0;
493	    int i;
494	    for (i = 0; i < 16; i += 3)
495	      {
496	        uint32_t v = (wskey[i] << 16);
497	        if (i + 1 < 16) v |= (wskey[i + 1] << 8);
498	        if (i + 2 < 16) v |= wskey[i + 2];
499	        wskey_b64[o++] = b64[(v >> 18) & 0x3f];
500	        wskey_b64[o++] = b64[(v >> 12) & 0x3f];
501	        wskey_b64[o++] = (i + 1 < 16) ? b64[(v >> 6) & 0x3f] : '=';
502	        wskey_b64[o++] = (i + 2 < 16) ? b64[v & 0x3f] : '=';
503	      }
504	
505	    wskey_b64[o] = '\0';
506	  }
507	
508	  snprintf(req, sizeof(req),
509	    "GET %s HTTP/1.1\r\n"
510	    "Host: %s\r\n"
511	    "Upgrade: websocket\r\n"
512	    "Connection: Upgrade\r\n"
513	    "Sec-WebSocket-Key: %s\r\n"
514	    "Sec-WebSocket-Version: 13\r\n"
515	    "Authorization: Bearer %s\r\n"
516	    "Device-Id: %s\r\n"
517	    "Client-Id: %s\r\n"
518	    "Protocol-Version: 3\r\n"
519	    "\r\n",
520	    pathwithtok, host, wskey_b64, token, device_id, client_id);
521	
522	  printf("[xiaozhi] sending ws upgrade request (%zu bytes)\n", strlen(req));
523	
524	  ret = ws_tls_write_all(ws, (const uint8_t *)req, strlen(req));
525	  if (ret != 0)
526	    {
527	      return ret;
528	    }
529	
530	  /* Read the HTTP response line + headers until blank line. */
531	  {
532	    char line[256];
533	    int got101 = 0;
534	
535	    /* Read line-by-line until \r\n\r\n */
536	    for (;;)
537	      {
538	        size_t li = 0;
539	        char prev = 0;
540	
541	        while (li < sizeof(line) - 1)
542	          {
543	            uint8_t b;
544	            ret = ws_tls_read_all(ws, &b, 1);
545	            if (ret != 0)
546	              {
547	                return ret;
548	              }
549	
550	            line[li] = (char)b;
551	            if (line[li] == '\n' && prev == '\r')
552	              {
553	                break;
554	              }
555	
556	            prev = line[li];
557	            li++;
558	          }
559	
560	        line[li] = '\0';
561	
562	        /* Strip trailing \r\n */
563	        while (li > 0 && (line[li - 1] == '\r' || line[li - 1] == '\n'))
564	          {
565	            line[--li] = '\0';
566	          }
567	
568	        if (li == 0)
569	          {
570	            break;  /* blank line: end of headers */
571	          }
572	
573	        if (strstr(line, "101") != NULL && !got101)
574	          {
575	            got101 = 1;
576	          }
577	
578	        printf("[xiaozhi] <<< %s\n", line);
579	      }
580	
581	    if (!got101)
582	      {
583	        printf("[xiaozhi] ws upgrade failed (no 101)\n");
584	        return -EIO;
585	      }
586	  }
587	
588	  ws->connected = true;
589	  printf("[xiaozhi] WebSocket connected & upgraded\n");
590	  return 0;
591	}
592	
593	int xiaozhi_ws_send_text(struct xiaozhi_ws_s *ws, const char *data,
594	                         size_t len)
595	{
596	  if (!ws->connected)
597	    {
598	      return -ENOTCONN;
599	    }
600	
601	  return ws_send_frame(ws, WS_OPCODE_TEXT, (const uint8_t *)data, len);
602	}
603	
604	int xiaozhi_ws_send_binary(struct xiaozhi_ws_s *ws,
605	                           const uint8_t *data, size_t len)
606	{
607	  if (!ws->connected)
608	    {
609	      return -ENOTCONN;
610	    }
611	
612	  return ws_send_frame(ws, WS_OPCODE_BINARY, data, len);
613	}
614	
615	int xiaozhi_ws_recv(struct xiaozhi_ws_s *ws, const uint8_t **payload,
616	                    size_t *plen, bool *is_binary)
617	{
618	  uint8_t hdr[2];
619	  uint8_t mask[4];
620	  uint8_t opcode;
621	  bool masked;
622	  uint64_t plen64;
623	  int ret;
624	
625	  if (!ws->connected)
626	    {
627	      return -ENOTCONN;
628	    }
629	
630	  /* Read the first 2 bytes of the frame header. */
631	  ret = ws_tls_read_all(ws, hdr, 2);
632	  if (ret != 0)
633	    {
634	      return ret;
635	    }
636	
637	  opcode = hdr[0] & 0x0f;
638	  masked = (hdr[1] & WS_MASK_BIT) != 0;
639	  plen64 = hdr[1] & 0x7f;
640	
641	  if (plen64 == 126)
642	    {
643	      uint8_t ext[2];
644	      ret = ws_tls_read_all(ws, ext, 2);
645	      if (ret != 0)
646	        {
647	          return ret;
648	        }
649	
650	      plen64 = ((uint64_t)ext[0] << 8) | ext[1];
651	    }
652	  else if (plen64 == 127)
653	    {
654	      uint8_t ext[8];
655	      ret = ws_tls_read_all(ws, ext, 8);
656	      if (ret != 0)
657	        {
658	          return ret;
659	        }
660	
661	      plen64 = 0;
662	      for (int i = 0; i < 8; i++)
663	        {
664	          plen64 = (plen64 << 8) | ext[i];
665	        }
666	    }
667	
668	  if (masked)
669	    {
670	      ret = ws_tls_read_all(ws, mask, 4);
671	      if (ret != 0)
672	        {
673	          return ret;
674	        }
675	    }
676	
677	  if (plen64 > ws->rxbuf_cap)
678	    {
679	      printf("[xiaozhi] frame too large: %llu\n",
680	             (unsigned long long)plen64);
681	      return -EMSGSIZE;
682	    }
683	
684	  /* Read the payload. */
685	  if (plen64 > 0)
686	    {
687	      ret = ws_tls_read_all(ws, ws->rxbuf, plen64);
688	      if (ret != 0)
689	        {
690	          return ret;
691	        }
692	
693	      if (masked)
694	        {
695	          for (uint64_t i = 0; i < plen64; i++)
696	            {
697	              ws->rxbuf[i] ^= mask[i & 3];
698	            }
699	        }
700	    }
701	
702	  /* Handle control frames transparently. */
703	  if (opcode == WS_OPCODE_CLOSE)
704	    {
705	      printf("[xiaozhi] server sent close frame\n");
706	      ws->connected = false;
707	      return -ECONNRESET;
708	    }
709	
710	  if (opcode == WS_OPCODE_PING)
711	    {
712	      /* Echo as pong. */
713	      ws_send_frame(ws, WS_OPCODE_PONG, ws->rxbuf, plen64);
714	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
715	    }
716	
717	  if (opcode == WS_OPCODE_PONG)
718	    {
719	      /* Ignore. */
720	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
721	    }
722	
723	  /* Text or binary. */
724	  *payload    = ws->rxbuf;
725	  *plen       = plen64;
726	  *is_binary  = (opcode == WS_OPCODE_BINARY);
727	  return 0;
728	}
729	
730	void xiaozhi_ws_close(struct xiaozhi_ws_s *ws)
731	{
732	  if (ws->connected)
733	    {
734	      uint8_t close_frame[] = { 0x88, 0x00 };
735	      ws_tls_write_all(ws, close_frame, 2);
736	    }
737	
738	  mbedtls_ssl_close_notify(&ws->ssl);
739	  mbedtls_ssl_free(&ws->ssl);
740	  mbedtls_ssl_config_free(&ws->conf);
741	  mbedtls_ctr_drbg_free(&ws->ctr_drbg);
742	  mbedtls_entropy_free(&ws->entropy);
743	
744	  if (ws->fd >= 0)
745	    {
746	      close(ws->fd);
747	      ws->fd = -1;
748	    }
749	
750	  if (ws->rxbuf)
751	    {
752	      free(ws->rxbuf);
753	      ws->rxbuf = NULL;
754	    }
755	
756	  ws->connected = false;
757	}
