24	/* TLS ops backed by mbedtls (xiaozhi_ota_tls.c). The webclient refuses
25	 * "https" URLs with -ENOTSUP unless a tls_ops vector is provided.
26	 */
27	extern const struct webclient_tls_ops g_xz_tls_ops;
28	
29	/****************************************************************************
30	 * Pre-processor Definitions
31	 ****************************************************************************/
32	
33	#define OTA_URL "https://api.tenclass.net/xiaozhi/ota/"
34	#define OTA_BUF_SIZE  4096
35	
36	/****************************************************************************
37	 * Private Types
38	 ****************************************************************************/
39	
40	/* Context passed to the sink callback to accumulate the response body. */
41	
42	struct ota_sink_ctx_s
43	{
44	  char *buf;
45	  size_t cap;
46	  size_t len;
47	};
48	
49	/****************************************************************************
50	 * Private Functions
51	 ****************************************************************************/
52	
53	/* sink_callback: consume response body (the OTA JSON) into our buffer. */
54	
55	static CODE int ota_sink_callback(FAR char **buffer, int offset, int datend,
56	                                  FAR int *buflen, FAR void *arg)
57	{
58	  struct ota_sink_ctx_s *ctx = arg;
59	  int chunk = datend - offset;
60	
61	  if (chunk <= 0)
62	    {
63	      return 0;
64	    }
65	
66	  if (ctx->len + chunk >= ctx->cap)
67	    {
68	      chunk = ctx->cap - ctx->len - 1;
69	      if (chunk <= 0)
70	        {
71	          return -ENOMEM;
72	        }
73	    }
74	
75	  memcpy(ctx->buf + ctx->len, *buffer + offset, chunk);
76	  ctx->len += chunk;
77	  ctx->buf[ctx->len] = '\0';
78	  return 0;
79	}
80	
81	/****************************************************************************
82	 * Public Functions
83	 ****************************************************************************/
84	
85	/* Build the fixed OTA request body. mac is the device MAC string. */
86	
87	static int build_ota_body(const char *mac, FAR char *out, size_t outsz)
88	{
89	  /* A minimal but server-accepted OTA body. The xiaozhi server is tolerant
90	   * about most fields; mac_address is the important one (also sent as the
91	   * Device-Id header).
92	   */
93	
94	  return snprintf(out, outsz,
95	    "{\"flash_size\":16777216,\"minimum_free_heap_size\":8318916,"
96	    "\"mac_address\":\"%s\",\"chip_model_name\":\"esp32s3\","
97	    "\"chip_info\":{\"model\":9,\"cores\":2,\"revision\":2,\"features\":18},"
98	    "\"application\":{\"name\":\"xiaozhi\",\"version\":\"0.9.9\","
99	    "\"compile_time\":\"Jan 22 2025T20:40:23Z\","
100	    "\"idf_version\":\"v5.3.2-dirty\","
101	    "\"elf_sha256\":\"22986216df095587c42f8aeb06b239781c68ad8df80321e260556da7fcf5f522\"},"
102	    "\"partition_table\":[],\"ota\":{\"label\":\"factory\"},"
103	    "\"board\":{\"type\":\"bread-compact-wifi\",\"ssid\":\"mzy\","
104	    "\"rssi\":-58,\"channel\":6,\"ip\":\"192.168.124.38\","
105	    "\"mac\":\"cc:ba:97:20:b4:bc\"}}",
106	    mac);
107	}
108	
109	/* Perform the OTA POST and fill ota_out with ws_url / ws_token.
110	 * Returns 0 on success, negative errno on failure.
111	 */
112	
113	int xiaozhi_ota_fetch(const char *mac, FAR struct xiaozhi_ota_config_s *ota_out)
114	{
115	  struct webclient_context ctx;
116	  char body[OTA_BUF_SIZE];
117	  struct ota_sink_ctx_s sink;
118	  char buf[OTA_BUF_SIZE];         /* webclient http scratch */
119	  char sink_buf[OTA_BUF_SIZE];    /* distinct response-body accumulator */
120	  const char *headers[2];
121	  int ret;
122	  size_t bodylen;
123	  cJSON *root = NULL;
124	  cJSON *ws = NULL;
125	  cJSON *url = NULL;
126	  cJSON *token = NULL;
127	
128	  if (mac == NULL || ota_out == NULL)
129	    {
130	      return -EINVAL;
131	    }
132	
133	  memset(ota_out, 0, sizeof(*ota_out));
134	
135	  /* Build request body. */
136	  bodylen = build_ota_body(mac, body, sizeof(body));
137	
138	  /* Device-Id header = MAC. */
139	  headers[0] = "Device-Id: ";
140	  /* The webclient appends header lines as-is; we pass a small array. */
141	  /* NOTE: webclient treats each "headers[]" entry as a full header line
142	   * including the trailing CRLF-less content; it appends "\r\n".
143	   * We build the Device-Id header dynamically below.
144	   */
145	
146	  /* The headers array requires fully formed header strings. We can't
147	   * use a string literal with the MAC embedded, so build it in `buf`
148	   * side buffer. Reuse a small static-ish local.
149	   */
150	  {
151	    static char device_id_header[64];
152	    snprintf(device_id_header, sizeof(device_id_header),
153	             "Device-Id: %s", mac);
154	    headers[0] = device_id_header;
155	    headers[1] = "Content-Type: application/json";
156	  }
157	
158	  /* Set up sink to accumulate the response body. Use a SEPARATE buffer
159	   * from ctx.buffer: webclient reads into ctx.buffer and then calls our
160	   * sink_callback with a slice of that same ctx.buffer; if sink.buf ==
161	   * ctx.buffer we'd be memcpy-ing a region into itself (corrupting it).
162	   */
163	  memset(sink_buf, 0, sizeof(sink_buf));
164	  sink.buf = sink_buf;
165	  sink.cap = sizeof(sink_buf);
166	  sink.len = 0;
167	
168	  webclient_set_defaults(&ctx);
169	  ctx.method              = "POST";
170	  ctx.url                 = OTA_URL;
171	  ctx.protocol_version    = WEBCLIENT_PROTOCOL_VERSION_HTTP_1_1;
172	  ctx.buffer              = buf;            /* shared scratch buffer */
173	  ctx.buflen              = sizeof(buf);
174	  ctx.headers             = headers;
175	  ctx.nheaders            = 2;
176	  ctx.bodylen             = bodylen;
177	  ctx.timeout_sec         = 15;
178	  ctx.sink_callback       = ota_sink_callback;
179	  ctx.sink_callback_arg   = &sink;
180	
181	  /* Provide the mbedtls TLS backend so the https:// OTA URL works. */
182	  ctx.tls_ops             = &g_xz_tls_ops;
183	  ctx.tls_ctx             = NULL;
184	
185	  /* Provide the request body via the static-body helper. */
186	  webclient_set_static_body(&ctx, body, bodylen);
187	
188	  ret = webclient_perform(&ctx);
189	  if (ret != 0)
190	    {
191	      printf("[xiaozhi] OTA webclient_perform failed: %d\n", ret);
192	      return ret;
193	    }
194	
195	  printf("[xiaozhi] OTA HTTP status=%u, body=%zu bytes\n",
196	         ctx.http_status, sink.len);
197	
198	  if (ctx.http_status != 200 || sink.len == 0)
199	    {
200	      printf("[xiaozhi] OTA unexpected status/body: %u\n", ctx.http_status);
